from common import *
from scipy.optimize import least_squares
W0=2*np.pi*60
DEC=10; h=0.01
def prep(n): return load(n).iloc[::DEC].reset_index(drop=True)
names=['A_vref_op1','A_vref_op3','A_gentrip_op1','A_amb_op1','A_amb_op2','A_line_op3','A_load_op2']
data={n:prep(n) for n in names}
pp=np.load('pp.npy')
def simQm(p,d):
    K,Tq,kP,d1,d2,d3=p
    Kp,Tpd,Tw=pp
    th=d.bus_angle_rad.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values
    P0=d.active_power_pu.values[0]; Q0=d.reactive_power_pu.values[0]; V0=V[0]; Vs0=Vs[0]; th0=th[0]
    xt=th0; xP=P0; xq=Q0
    P=np.zeros(len(th)); Q=np.zeros(len(th))
    for k in range(len(th)):
        P[k]=xP
        Q[k]=xq+d1*(V[k]-V0)+d2*(Vs[k]-Vs0)+d3*(xP-P0)
        wf=(th[k]-xt)/(Tw*W0)
        xt+=h*(th[k]-xt)/Tw
        xP+=h*(P0-Kp*wf-xP)/Tpd
        xq+=h*((Q0+K*(Vs[k]-V[k])+kP*(xP-P0)-xq)/Tq)
    return P,Q
def resQ(p):
    return np.concatenate([simQm(p,data[n])[1]-data[n].reactive_power_pu.values for n in names])
best=None
for K0 in [10,30]:
  for T0 in [1.0,6.0]:
    s=least_squares(resQ,[K0,T0,0,0,0,0],bounds=([0,0.05,-100,-50,-50,-50],[200,60,100,50,50,50]),x_scale='jac',max_nfev=200)
    rm=np.sqrt(np.mean(s.fun**2)); print(np.round(s.x,3),rm)
    if best is None or rm<best[1]: best=(s.x,rm)
p=best[0]; print('best',np.round(p,4),best[1])
for n in names:
    P,Q=simQm(p,data[n]); print(n,'P %.5f Q %.5f'%(np.sqrt(np.mean((P-data[n].active_power_pu)**2)),np.sqrt(np.mean((Q-data[n].reactive_power_pu)**2))))
np.save('qsimple.npy',p)

